    {
      "name": "Floating Icon Tile",
      "role": "Inline visual accent or social proof marker",
      "description": "14–24px radius square or pill, white or carbon fill, 1px black border. Holds a single monochrome icon or tiny product image. Appears scattered around hero and section compositions."
    },
    {
      "name": "Top Navigation Bar",
      "role": "Primary site navigation",
      "description": "White or transparent, no border. Logo mark (geometric '□△' wordmark) in #000000 left, nav links in Unica77 500 at 18px, right. Sticky optional. No background blur — the page is quiet enough not to need it."
    },
    {
      "name": "Price Block",
      "role": "Prominent pricing display",
      "description": "Unica77 700 at 45–60px, #000000 on white, or white on Carbon. Original price struck through in Whyte Semi-Mono 400 at 27px in #999999. Currency superscript at 0.5em."
    },
    {
      "name": "Section Headline Stack",
      "role": "Above-the-fold title + subtitle + CTA",
      "description": "Two-line Unica77 700 headline at 70–100px with letter-spacing -0.04em, line-height 0.92–0.96. Subtitle in Unica77 400 at 25–30px, #000000. Primary CTA sits centered below the subtitle with 24–30px gap."
    },
    {
      "name": "Hero Conic Sphere",
      "role": "Decorative hero accent",
      "description": "Round graphic with full conic gradient (blue → purple → red → orange → yellow → green → blue), no border, placed bottom-left of the hero composition. The only ornamental gradient in the system."
    }
  ],
  "dos": [
    "Use #0000ff as the sole chromatic action color — CTAs, active states, product surfaces, and chromatic borders all read from one swatch.",
    "Push display sizes to 70px and above; tighten letter-spacing to -0.04em at those sizes so headlines read as blocks, not lines.",
    "Engage Unica77 stylistic alternates (ss01–ss09) so headings, UI, and product mockups each pick a distinct voice from the same family.",
